<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#344054}h1{font-size:22px;color:#142d43}h2{font-size:15px;margin-top:25px}table{width:100%;border-collapse:collapse}th{background:#edf4fa;text-align:left}td,th{padding:7px;border-bottom:1px solid #e4e7ec}.note{color:#667085}.warning{color:#b54708}.page{page-break-before:always}</style></head><body><table style="margin-bottom:18px"><tr><td style="width:72px;border:0;padding:0"><img src="{{ public_path('images/umg/escudo-umg.png') }}" alt="UMG" width="60" height="60"></td><td style="border:0;padding:0"><strong>{{ config('academico.universidad') }}</strong><br>{{ config('academico.curso') }} · {{ config('academico.tipo') }}<br>{{ config('academico.estudiante') }} · {{ config('academico.semestre') }}</td></tr></table><h1>Optimización de tickets · Resumen de resultados</h1><p class="note">Generado: {{ now()->format('d/m/Y H:i') }} · {{ $tickets->count() }} tickets según los filtros seleccionados.</p><p>Carga ponderada total: {{ number_format($tickets->sum(fn($t)=>$c->peso($t)),2) }} · Tickets abiertos: {{ $tickets->where('estado','Abierto')->count() }} · Ruta B: {{ $tickets->where('ruta','B')->count() }}</p><table><thead><tr><th>Ticket</th><th>Evento</th><th>Prioridad</th><th>Gestor</th><th>Docente</th><th>Inicio</th><th>Carga</th></tr></thead><tbody>@foreach($tickets as $t)<tr><td>{{ $t->codigo }}</td><td>{{ $t->evento_formativo }}</td><td>{{ $t->prioridad }}</td><td>{{ $t->gestor?->nombre }}</td><td>{{ $t->tipo_docente }}</td><td>{{ $t->fecha_inicio?->format('d/m/Y')??'Sin fecha' }}</td><td>{{ $c->peso($t) }}</td></tr>@endforeach</tbody></table><div class="page"><h2>Calendario de supervisión por gestor</h2><p class="note">{{ $run?'Corrida aplicada #'.$run->id:'No hay una corrida aplicada.' }}</p>@if($stale)<p class="warning">Calendario desactualizado: los datos cambiaron desde su aplicación. Genere una nueva corrida.</p>@endif @foreach(collect($calendar)->groupBy('gestor') as $name=>$rows)<h2>{{ $name }}</h2><table><thead><tr><th>Fecha</th><th>Ticket</th><th>Supervisión</th></tr></thead><tbody>@foreach($rows->sortBy('fecha') as $row)<tr><td>{{ \Carbon\Carbon::parse($row['fecha'])->format('d/m/Y') }}</td><td>{{ $row['ticket'] }}</td><td>{{ ucfirst($row['tipo']) }}</td></tr>@endforeach</tbody></table>@endforeach</div></body></html>
